/* Additional standalone examples for every room and navigation stage. */
(()=>{
 const trainer=id=>id==='mrfuji'?'<span class="overworld-portrait fuji" role="img" aria-label="Sr. Fuji"></span>':'<img src="../../assets/showdown/trainers/'+id+'.png" alt="Personagem do encontro">';
 const mon=id=>'<img class="mon" src="../../assets/pokeapi/sprites/pokemon/'+id+'.png" alt="Pokémon do encontro">';
 const terminal='<img src="../../assets/mode-art/rocket-terminal.svg" alt="Terminal Rocket">';
 const choice=(name,hint,result)=>[name,hint,result];
 const entries={};
 function add(id,label,speaker,art,pages,choices,summary='SEM COMBATE',location='Base escondida'){entries[id]={label,kind:'OPERAÇÃO ROCKET / '+summary,heading:label,speaker,location,art,pages,choices,reward:'<span>'+summary+'</span>'}}
 add('entry','Início da operação','CONTATO DA RESISTÊNCIA',trainer('oak'),['A entrada fica atrás do salão de jogos de Celadon. Há Pokémon presos lá dentro.','Monte sua equipe, escolha os corredores com cuidado e recupere o Silph Scope das mãos de Giovanni.'],[choice('Continuar tentativa','Retomar de onde parou','Você retomará o último encontro salvo.'),choice('Nova operação','Escolher três Pokémon','Sua equipe começará com três Pokémon básicos e 10 de ouro.'),choice('Voltar à biblioteca','Escolher outro modo','A tentativa atual continua salva.')],'DOSSIÊ 01');
 add('starter','Prepare sua equipe','CONTATO DA RESISTÊNCIA',mon(1),['Antes de entrar, escolha três parceiros. Os três começam com uma estrela.','Combine resistência e alcance. Uma quarta vaga fica disponível para reforçar sua equipe.'],[choice('Bulbasaur · Charmander · Squirtle','Exemplo de trio equilibrado','Trio selecionado para esta demonstração.'),choice('Voltorb · Gastly · Machop','Exemplo de trio ofensivo','Trio selecionado para esta demonstração.'),choice('Começar infiltração','Confirmar sua equipe','Na versão integrada, a seleção será feita entre os seis Pokémon.')],'SELEÇÃO DE EQUIPE');
 add('map','Escolha o próximo caminho','COMUNICADOR',terminal,['Encontramos duas rotas para o próximo setor. Você só precisa entrar em uma delas.','A patrulha guarda o corredor principal. Já o abrigo pode dar tempo para recuperar sua equipe.'],[choice('Patrulha Rocket','Combate · 6 ouro e 2 XP','A patrulha percebeu sua aproximação. Prepare sua equipe.'),choice('Abrigo','Recuperar vida ou reduzir alerta','Um corredor silencioso leva ao abrigo.'),choice('Salvar e sair','Guardar o progresso','O caminho continua disponível para quando você voltar.')],'ESCOLHA DE CAMINHO');
 add('patrol','Patrulha Rocket','RECRUTA ROCKET',trainer('rocketgrunt'),['Ei! Essa área é restrita! Você não tem autorização para estar aqui.','Se quiser continuar, vai ter que passar pela minha equipe!'],[choice('Preparar equipe','Vitória: 6 ouro e 2 XP','Organize seus Pokémon antes de começar a batalha.'),choice('Salvar e sair','Retomar este encontro','A patrulha permanece nesta etapa.')],'COMBATE');
 add('cells','Celas vigiadas','RECRUTA ROCKET',trainer('rocketgruntf'),['Afaste-se das celas! Esses Pokémon estão sob a nossa guarda.','Não importa o que você ouviu. Ninguém vai sair daqui sem lutar!'],[choice('Enfrentar os guardas','5 ouro · 2 XP · resgate','Após vencer, você decidirá o destino do Pokémon libertado.'),choice('Salvar e sair','Continuar depois','Os guardas e o Pokémon continuam no mesmo encontro.')],'COMBATE / RESGATE');
 add('depot','Depósito de equipamentos','COMUNICADOR',terminal,['Os armários ainda estão fechados, mas a chave estava no terminal dos guardas.','Escolha um equipamento para sua mochila. Ele pode ajudar na próxima batalha.'],[choice('Faixa de ataque','Equipamento ofensivo','O equipamento escolhido irá para a mochila.'),choice('Proteção reforçada','Equipamento defensivo','A proteção escolhida irá para a mochila.'),choice('Sino de recuperação','Equipamento de sustentação','O sino escolhido irá para a mochila.')],'ESCOLHA 1 EQUIPAMENTO');
 add('shelter','Um lugar para respirar','CONTATO DA RESISTÊNCIA',mon(113),['Aqui os guardas não conseguem ver vocês. Aproveitem para respirar.','Podemos cuidar dos ferimentos, esconder seus rastros ou preparar a equipe para o próximo combate.'],[choice('Recuperar vida','+5 de vida','Sua equipe descansa. Você recupera 5 de vida, até o limite de 100.'),choice('Esconder os rastros','−1 alerta','Os Rockets perdem seu rastro. O alerta diminui em 1.'),choice('Preparar reforço','+12% ataque e vida · próxima luta','O reforço será aplicado somente na próxima batalha.')],'ABRIGO');
 add('shop','O contrabandista','CONTRABANDISTA',trainer('scientist'),['Fale baixo. Os Rockets não sabem que eu ajudo os treinadores que passam por aqui.','Tenho Pokémon e suprimentos. Faça suas compras antes que a patrulha volte.'],[choice('Abrir loja','Comprar com o ouro da tentativa','Na versão integrada, a loja real aparecerá para você comprar e organizar a equipe.'),choice('Concluir compras','Seguir a operação','As compras serão encerradas e o próximo caminho ficará disponível.'),choice('Salvar e sair','Voltar depois','A loja e sua equipe continuam salvas.')],'LOJA');
 add('laboratory','Experimentos interrompidos','CIENTISTA',trainer('scientist'),['Eles usaram esta sala para testar equipamentos nos Pokémon. Não podemos deixá-los aqui.','Consigo abrir uma cápsula ou recuperar os equipamentos antes de desligar tudo.'],[choice('Libertar o Pokémon','Resgate com duas estrelas','Você decidirá se o Pokémon entra na equipe ou segue para segurança.'),choice('Recuperar equipamentos','Duas cópias de um equipamento','Escolha o equipamento que irá para sua mochila.')],'LABORATÓRIO');
 add('employee','Funcionário disfarçado','FUNCIONÁRIO',trainer('scientist'),['Sou da manutenção! Se você me tirar daqui, consigo abrir os controles da base.','Preciso atravessar dois corredores guardados. Depois, entrego meu cartão de acesso e mostro onde ficam as lojas.'],[choice('Escoltar funcionário','Vencer duas batalhas · receber cartão','A escolta começa. Derrotas não apagam as vitórias já obtidas.'),choice('Pedir rota segura','−1 alerta · sem escolta','O funcionário aponta uma passagem com menos vigilância.')],'MISSÃO EXTRA');
 add('convoy','Comboio interceptado','OFICIAL ROCKET',trainer('ariana'),['Esse transporte sai agora. Tire seus Pokémon do caminho!','Nossa escolta não vai entregar a carga para um intruso.'],[choice('Preparar equipe','10 ouro · 3 XP · escolha de resgate','Vença a escolta para escolher um dos Pokémon transportados.'),choice('Salvar e sair','Retomar a interceptação','O comboio ficará reservado neste encontro.')],'COMBATE / TRANSPORTE');
 add('research','Arquivo de pesquisas','COMUNICADOR',terminal,['Esses documentos mostram como a Rocket organiza o estoque de Pokémon.','Escolha uma linha da sua equipe. Podemos localizar cópias dela nas próximas três lojas, enquanto houver estoque.'],[choice('Pesquisar linha de frente','Selecionar um aliado','Na versão integrada, escolha a espécie da sua equipe que deseja desenvolver.'),choice('Ver todas as linhas','Escolher outro aliado','As linhas elegíveis da equipe serão apresentadas.'),choice('Seguir sem pesquisar','Concluir sem recompensa','Nenhuma pesquisa será iniciada.')],'PESQUISA');
 add('training','Uma pausa para treinar','INSTRUTOR',mon(66),['Tem espaço suficiente aqui para praticar sem chamar os guardas.','Podemos fortalecer a equipe inteira ou procurar mais um parceiro de uma linha que você já tem.'],[choice('Treinar a equipe','+6 XP','A experiência ajuda a liberar mais vagas no campo.'),choice('Reforçar uma linha','Uma cópia básica de um aliado','Escolha uma linha da sua equipe para receber uma cópia básica.')],'TREINAMENTO');
 add('trap','O corredor tem sensores','COMUNICADOR',terminal,['Espere! Há um sensor no chão. Se pisar nele, os guardas vão perceber.','Podemos pagar para desativar o sistema ou enfrentar a segurança.'],[choice('Desativar sistema','−4 ouro · sem combate','Com ouro suficiente, o sensor será desligado.'),choice('Enfrentar os guardas','+1 alerta · combate','Os guardas chegam. Vença para abrir passagem.')],'ARMADILHA');
 add('blackmarket','Mercado clandestino','NEGOCIANTE',trainer('gentleman'),['Procurando um parceiro específico? Tenho contatos que a loja comum não oferece.','Escolha uma linha da sua equipe. O preço é o custo normal mais três de ouro.'],[choice('Ver Pokémon disponíveis','Cópias básicas dos seus aliados','A lista mostrará preço, espécie e disponibilidade de estoque.'),choice('Seguir sem comprar','Manter o ouro','Nenhum recurso será gasto.')],'COMPRA ESPECIAL');
 add('locked','Depósito trancado','COMUNICADOR',terminal,['A porta está reforçada. Um cartão de acesso abre a fechadura sem barulho.','Se não tiver um cartão, ainda dá para arrombar. Mas isso vai chamar atenção.'],[choice('Usar cartão','Consome 1 cartão · sem alerta','A porta se abre. Você escolherá um equipamento.'),choice('Arrombar a porta','+2 alerta','O barulho ecoa pelo setor. Escolha um equipamento antes de sair.')],'SUPRIMENTOS');
 add('intercept','Uma transmissão suspeita','RÁDIO ROCKET',terminal,['“Patrulha, confirmem as posições. O intruso ainda está neste setor.”','Podemos usar esta frequência para descobrir os próximos três encontros e evitar uma patrulha comum.'],[choice('Guardar informações','Revelar rotas · evitar 1 patrulha','Você recebe informações das próximas rotas. Evitar uma patrulha não concede recompensa.'),choice('Seguir em silêncio','Concluir sem usar a frequência','A comunicação continua sem que os Rockets percebam.')],'INTELIGÊNCIA');
 add('checkpoint','Setor concluído','COMUNICADOR',terminal,['Vocês passaram pelo último bloqueio deste setor. Há uma saída de emergência logo adiante.','Continuar mantém os resgates e aproxima a equipe de Giovanni. Extrair encerra esta tentativa; salvar permite voltar depois.'],[choice('Continuar infiltração','Seguir para o próximo setor','O próximo setor da base está disponível.'),choice('Extrair e encerrar','Registrar os resgates · terminar tentativa','No jogo, haverá uma confirmação antes de encerrar a tentativa.'),choice('Salvar e sair','Continuar esta tentativa depois','Sua equipe, recursos e resgates serão guardados.')],'PONTO DE EXTRAÇÃO');
 add('defeat','A dupla levou a melhor','JESSIE E JAMES','DUO',['Jessie: Eu avisei! Ninguém passa pela Equipe Rocket assim tão fácil!','James: E esses três de ouro vão ajudar nos nossos planos. Quer de volta? Vença a revanche!'],[choice('Preparar revanche','Recuperar 3 de ouro ao vencer','A equipe da dupla permanece com a mesma força. O roubo não se repete neste encontro.'),choice('Salvar e sair','Revanche e saque ficam salvos','A revanche poderá ser retomada nesta mesma etapa.')],'DERROTA / REVANCHE');
 add('boss','Giovanni espera por você','GIOVANNI',trainer('giovanni'),['Então foi você que atravessou a minha base inteira. Preciso admitir: sua equipe chegou longe.','Mas o Silph Scope vai ficar comigo. Mostre se consegue derrotar o líder da Equipe Rocket.'],[choice('Preparar equipe','Confronto final de Celadon','Organize sua equipe. A vitória conclui a Base Escondida.'),choice('Salvar e sair','Retomar antes do confronto','Você poderá voltar para enfrentar Giovanni com a mesma equipe.')],'CHEFE / ETAPA 50');
 add('ending','Silph Scope recuperado','CONTATO DA RESISTÊNCIA',trainer('oak'),['Giovanni recuou. Os Pokémon estão livres e o Silph Scope está em segurança.','Agora podemos seguir para Lavender. Há relatos de um espírito na Torre Pokémon... e o Sr. Fuji ainda não voltou de lá.'],[choice('Ecos de Lavender','Ver o próximo capítulo','O Silph Scope desbloqueia a próxima operação.'),choice('Ver resultado','Pontuação e resgates','O resultado mostra as etapas concluídas, resgates, vida e maior alerta.'),choice('Voltar à biblioteca','Escolher outro modo','A conclusão de Celadon continua registrada.')],'MISSÃO CONCLUÍDA');
 add('memorial','Memorial silencioso','MÉDIUM',trainer('medium'),['Fale baixo. Este é um lugar de lembranças e despedidas.','Sua equipe pode descansar aqui ou refletir sobre o caminho que percorreu.'],[choice('Descansar','+5 de vida','Você recupera 5 de vida.'),choice('Refletir','+4 XP','Sua equipe recebe 4 XP.')],'LAVENDER / MEMORIAL','Torre Pokémon');
 add('mist','Entre os ecos da torre','COMUNICADOR',terminal,['O Silph Scope revela formas entre a névoa. Agora você distingue os espíritos dos guardas escondidos.','Quer procurar uma passagem segura ou vasculhar os suprimentos deixados no corredor?'],[choice('Revelar rota','−1 alerta · próximos três encontros','O Silph Scope não é consumido e as próximas rotas ficam visíveis.'),choice('Buscar suprimentos','+5 ouro · +1 alerta','Você encontra ouro, mas chama a atenção dos Rockets.')],'LAVENDER / NÉVOA','Torre Pokémon');
 add('medium','Uma voz entre os ecos','MÉDIUM',trainer('medium'),['Não são os espíritos que ameaçam esta torre. Os homens de preto levaram o Sr. Fuji para o alto.','Conheço um refúgio. Também posso oferecer proteção para a sua equipe.'],[choice('Encontrar refúgio','−2 alerta','Os Rockets perdem seu rastro.'),choice('Aceitar proteção','Reforço na próxima batalha','Sua equipe recebe proteção para uma batalha.')],'LAVENDER / ENCONTRO','Torre Pokémon');
 add('spirit','O espírito de Marowak','SILPH SCOPE',mon(105),['O Silph Scope revela a identidade do espírito. É Marowak, a mãe de Cubone.','Ela protege esta escadaria. Vença o encontro para acalmá-la e permitir que encontre paz.'],[choice('Preparar equipe','Apaziguar o espírito','Marowak não será capturada e este encontro não registra uma compra.'),choice('Salvar e sair','Continuar depois','A escadaria continua aguardando sua equipe.')],'LAVENDER / ETAPA 40','Escadaria da torre');
 add('fuji','O Sr. Fuji está a salvo','SR. FUJI',trainer('mrfuji'),['Muito obrigado. Vocês ajudaram os Pokémon da torre e deram paz ao espírito de Marowak.','Quero que fiquem com esta Poké Flauta. Que ela lembre vocês de tratar cada Pokémon com carinho.'],[choice('Concluir o capítulo','Registrar o resgate e a Poké Flauta','O resgate do Sr. Fuji e a Poké Flauta serão registrados como marcos da jornada.'),choice('Voltar à biblioteca','Escolher o próximo destino','Silph sob ataque será o próximo capítulo da operação.')],'LAVENDER / CONCLUSÃO','Refúgio do Sr. Fuji');
 window.ROCKET_DIALOGUE_SCENES=entries;
})();
